func (h *Handler) getMovie(w http.ResponseWriter, r *http.Request) {
	m, err := h.store.Find(r.PathValue("id"))          // one model
	if err != nil { http.Error(w, "not found", http.StatusNotFound); return }
	switch negotiate(r.Header.Get("Accept")) {
	case "application/json":
		w.Header().Set("Content-Type", "application/json"); _ = json.NewEncoder(w).Encode(m)
	case "text/csv":
		w.Header().Set("Content-Type", "text/csv"); _ = writeCSV(w, m)
	default:
		w.Header().Set("Content-Type", "text/html"); _ = h.movieTmpl.Execute(w, m)
	}
}
